def solve_langford(n, fixed_0_based):
    seq = [0] * (2 * n)
    for idx, val in fixed_0_based.items():
        seq[idx] = val

    # Find all valid placements for each number
    def solve(idx):
        if idx == 2 * n:
            return True
        if seq[idx] != 0:
            return solve(idx + 1)

        for v in range(1, n + 1):
            # If v is already fully placed, skip
            if seq.count(v) == 2:
                continue
            # If v is partially placed, we can only place it if it matches the distance
            if seq.count(v) == 1:
                first_idx = seq.index(v)
                if idx - first_idx == v + 1:
                    seq[idx] = v
                    if solve(idx + 1):
                        return True
                    seq[idx] = 0
                continue

            # If v is not placed at all
            if seq.count(v) == 0:
                if idx + v + 1 < 2 * n and seq[idx + v + 1] == 0:
                    seq[idx] = v
                    seq[idx + v + 1] = v
                    if solve(idx + 1):
                        return True
                    seq[idx] = 0
                    seq[idx + v + 1] = 0
        return False

    if solve(0):
        return seq
    return None

